const { withGradleProperties } = require('expo/config-plugins');

// AsyncStorage on Android is a SQLite database capped at 6 MB by default, and
// writes past the cap reject with SQLITE_FULL. A single long-running show's
// episode list can be about 5 MB, so subscribing to a few would hit it.
const PROPERTY_KEY = 'AsyncStorage_db_size_in_MB';
const DATABASE_SIZE_MB = '50';

// android/ is generated by prebuild and gitignored, so a hand edit to
// gradle.properties would be lost. This re-applies the setting on every prebuild.
module.exports = function withAndroidAsyncStorageSize(config) {
  return withGradleProperties(config, (gradleConfig) => {
    gradleConfig.modResults = gradleConfig.modResults.filter(
      (item) => !(item.type === 'property' && item.key === PROPERTY_KEY),
    );
    gradleConfig.modResults.push({
      type: 'property',
      key: PROPERTY_KEY,
      value: DATABASE_SIZE_MB,
    });
    return gradleConfig;
  });
};
